src/main.rs.contents:
use burn::cubecl::logging::{LaunchObservation, LaunchObserver};
use burn::module::{Module, Param};
use burn::optim::{AdamWConfig, AdamWExecutionConfig, GradientsParams, ModuleOptimizer};
use burn::tensor::{Device, Tensor, TensorData, Tolerance};
use burn_pack::Reader;
use std::sync::{
    Arc,
    atomic::{AtomicUsize, Ordering::Relaxed},
};

const VALUES: [[f32; 4]; 2] = [[1., -2., 3., -4.], [5., -6., 7., -8.]];
const GRADS: [[f32; 4]; 2] = [[0.5, -1., 2., -0.25], [-0.75, 0.125, -1.5, 3.]];

#[derive(Module, Debug)]
struct Model {
    weights: [Param<Tensor<1>>; 2],
}

#[derive(Default)]
struct Launches(AtomicUsize);
impl LaunchObserver for Launches {
    fn launched(&self, name: &'static str) {
        if name.contains("adamw_foreach::") {
            self.0.fetch_add(1, Relaxed);
        }
    }
}

fn optimizer(execution: AdamWExecutionConfig) -> ModuleOptimizer {
    AdamWConfig::new()
        .with_beta_1(0.5)
        .with_beta_2(0.5)
        .with_amsgrad(true)
        .with_weight_decay(0.1)
        .with_execution(Some(execution))
        .init()
}

fn close(a: &TensorData, b: &TensorData) {
    assert_eq!(a.dtype(), b.dtype());
    assert_eq!(a.shape(), b.shape());
    a.assert_approx_eq::<f32>(b, Tolerance::rel_abs(1e-5, 1e-6));
}

fn check_state(actual: &ModuleOptimizer, reference: &ModuleOptimizer) {
    let a = Reader::from_bytes(actual.into_bytes().unwrap()).unwrap();
    let b = Reader::from_bytes(reference.into_bytes().unwrap()).unwrap();
    assert_eq!(a.metadata(), b.metadata());
    assert_eq!(a.scalars(), b.scalars());
    let (mut a, mut b) = (a.into_tensors().unwrap(), b.into_tensors().unwrap());
    a.sort_by(|a, b| a.name.cmp(&b.name));
    b.sort_by(|a, b| a.name.cmp(&b.name));
    assert_eq!(a.len(), 6); // m1, m2 and AMSGrad max for both parameters.
    assert_eq!(a.len(), b.len());
    for (a, b) in a.into_iter().zip(b) {
        assert_eq!((&a.name, a.param_id), (&b.name, b.param_id));
        let a = TensorData::from_bytes(a.to_bytes().unwrap(), a.shape, a.dtype);
        let b = TensorData::from_bytes(b.to_bytes().unwrap(), b.shape, b.dtype);
        close(&a, &b);
    }
}

fn main() {
    let device = Device::cpu();
    let tracked = device.clone().autodiff();
    let make_model = || Model {
        weights: VALUES.map(|v| Param::from_data(v, &tracked)),
    };
    let mut actual = make_model();
    // Same logical IDs, independently allocated parameters and independent optimizer state.
    let mut reference = make_model();
    for (a, b) in actual.weights.iter().zip(&mut reference.weights) {
        b.id = a.id;
    }
    let mut foreach = optimizer(AdamWExecutionConfig::Foreach);
    let mut baseline = optimizer(AdamWExecutionConfig::Reference);
    let counts = Arc::new(Launches::default());
    let _observation = LaunchObservation::new(counts.clone());
    for step in 0..2 {
        let gradients = |model: &Model| {
            let mut grads = GradientsParams::new();
            for (param, values) in model.weights.iter().zip(GRADS) {
                let values = values.map(|g| g * if step == 0 { 1. } else { -0.5 });
                grads.register(param.id, Tensor::<1>::from_data(values, &device));
            }
            grads
        };
        let (a, b) = (gradients(&actual), gradients(&reference));
        actual = foreach.step(0.01, actual, a);
        reference = baseline.step(0.01, reference, b);
        for (a, b) in actual.weights.iter().zip(&reference.weights) {
            assert_eq!(a.id, b.id);
            assert!(a.val().is_require_grad());
            assert_eq!(a.val().device(), tracked);
            close(&a.val().to_data(), &b.val().to_data());
        }
        check_state(&foreach, &baseline);
        device.sync().unwrap();
        assert_eq!(counts.0.load(Relaxed), step + 1);
    }
    println!("PASS: two parameters, two steps, all six state tensors, two real batch launches");
}

